INSERT INTO recipes(id,title,servings,minutes,tags,steps,source) VALUES
('20000000-0000-4000-8000-000000000001','蒜蓉菠菜',2,10,ARRAY['清淡','快手'],ARRAY['菠菜洗净沥干，蒜切末','热锅加入估算用量的油，炒香蒜末，加入菠菜炒熟并调味'],'项目自编家庭参考菜谱 v1，份量和耗时为估计'),
('20000000-0000-4000-8000-000000000002','清炒小白菜',2,12,ARRAY['清淡','快手'],ARRAY['小白菜洗净切段，蒜切末','热锅加入油和蒜末，加入小白菜炒熟并调味'],'项目自编家庭参考菜谱 v1，份量和耗时为估计'),
('20000000-0000-4000-8000-000000000003','香菇炒青椒',2,15,ARRAY['家常','快手'],ARRAY['香菇和青椒洗净切片，蒜切末','热锅加油炒香蒜末，加入香菇炒至熟透','加入青椒翻炒熟透，调味出锅'],'项目自编家庭参考菜谱 v1，份量和耗时为估计'),
('20000000-0000-4000-8000-000000000004','番茄豆腐汤',2,20,ARRAY['家常','汤'],ARRAY['番茄洗净切块，豆腐切块，量取饮用水','热锅加油，将番茄炒软','加入饮用水和豆腐，煮沸后小火煮透并调味'],'项目自编家庭参考菜谱 v1，份量和耗时为估计'),
('20000000-0000-4000-8000-000000000005','黄瓜炒鸡蛋',2,15,ARRAY['家常','快手'],ARRAY['黄瓜洗净切片，鸡蛋打散','热锅加油，将鸡蛋炒熟盛出','黄瓜炒熟，加入鸡蛋翻匀并调味'],'项目自编家庭参考菜谱 v1，份量和耗时为估计'),
('20000000-0000-4000-8000-000000000006','胡萝卜炒鸡蛋',2,15,ARRAY['家常','快手'],ARRAY['胡萝卜洗净切细丝，鸡蛋打散','热锅加油，将鸡蛋炒熟盛出','将胡萝卜炒至软熟，加入鸡蛋翻匀并调味'],'项目自编家庭参考菜谱 v1，份量和耗时为估计'),
('20000000-0000-4000-8000-000000000007','芹菜炒豆干',2,12,ARRAY['家常','快手'],ARRAY['芹菜洗净切段，豆干切条','热锅加油，将芹菜和豆干炒至熟透并调味'],'项目自编家庭参考菜谱 v1，份量和耗时为估计'),
('20000000-0000-4000-8000-000000000008','卷心菜炒胡萝卜',2,12,ARRAY['清淡','快手'],ARRAY['卷心菜和胡萝卜洗净切细丝','热锅加油，先炒胡萝卜，再加卷心菜炒至软熟并调味'],'项目自编家庭参考菜谱 v1，份量和耗时为估计'),
('20000000-0000-4000-8000-000000000009','冬瓜虾汤',2,25,ARRAY['家常','汤'],ARRAY['冬瓜去皮切片，虾清洗处理，处理生虾后清洗双手和案板；量取水','加水煮沸，加入冬瓜煮至软熟','加入虾煮至熟透，按估算用量加入油和盐'],'项目自编家庭参考菜谱 v1，份量和耗时为估计'),
('20000000-0000-4000-8000-000000000010','土豆炖牛肉',2,60,ARRAY['家常','炖煮'],ARRAY['土豆和姜洗净切块，牛肉切小块；处理生肉后清洗双手和案板','热锅加油，将牛肉和姜翻炒，加入土豆和水','煮沸后小火炖煮，期间留意锅内水量','检查牛肉熟透、土豆软烂，按估算用量调味；必要时延长炖煮'],'项目自编家庭参考菜谱 v1，份量和耗时为估计'),
('20000000-0000-4000-8000-000000000011','南瓜米粥',2,45,ARRAY['早餐','清淡'],ARRAY['南瓜去皮切小块，大米淘洗，量取饮用水','将大米、南瓜和水放入锅中，煮沸后小火煮，留意溢锅与水量','检查米粒和南瓜软熟，搅匀；必要时延长煮制'],'项目自编家庭参考菜谱 v1，份量和耗时为估计'),
('20000000-0000-4000-8000-000000000012','番茄鸡蛋面',2,20,ARRAY['家常','主食'],ARRAY['番茄洗净切块，鸡蛋打散，量取水','热锅加油，将鸡蛋炒熟盛出','番茄炒软，加入水煮沸','加入面条煮至熟透，期间留意水量','加入熟鸡蛋，调味并充分加热后盛出'],'项目自编家庭参考菜谱 v1，份量和耗时为估计');
